-- =====================================================================================
-- E-commerce platform — database schema (PostgreSQL 18)
--
-- Two databases, one per service. The design and the reasons behind it are explained
-- in docs/database.md. The migrations in each service create exactly this schema.
--
--   gateway_db  — api-gateway (NestJS):    users, orders, stock  (+ copies of the catalog)
--   admin_db    — admin-service (Laravel): catalog               (+ copies of orders and stock)
--
-- Conventions
--   - ids are UUIDv7, generated by the application (no database default)
--   - money is integer cents, timestamps are timestamptz (UTC)
--   - names: {table}_pkey, {table}_{column}_foreign, {table}_{column}_unique,
--            {table}_{column}_index, {table}_{column}_check
--   - "COPY" tables are written only by the sync between the services: no foreign keys,
--     no CHECK constraints (the owning service already validated the data)
-- =====================================================================================


-- =====================================================================================
-- gateway_db — api-gateway (NestJS)
-- =====================================================================================
\connect gateway_db

CREATE TYPE user_role AS ENUM ('customer', 'admin');
CREATE TYPE order_status AS ENUM ('pending', 'paid', 'shipped', 'delivered', 'cancelled');
CREATE TYPE stock_movement_reason AS ENUM ('order_placed', 'order_cancelled', 'adjustment');

-- Customers and admins. Soft-deleted, so their orders stay intact.
CREATE TABLE users (
    id            uuid         NOT NULL,
    name          varchar(255) NOT NULL,
    email         varchar(255) NOT NULL,
    password_hash varchar(255) NOT NULL,
    role          user_role    NOT NULL DEFAULT 'customer',
    created_at    timestamptz  NOT NULL DEFAULT now(),
    updated_at    timestamptz  NOT NULL DEFAULT now(),
    deleted_at    timestamptz,
    CONSTRAINT users_pkey PRIMARY KEY (id),
    CONSTRAINT users_email_check CHECK (email = lower(email))
);
-- A deleted user's email can be registered again
CREATE UNIQUE INDEX users_email_unique ON users (email) WHERE deleted_at IS NULL;

-- COPY of admin_db.categories
CREATE TABLE categories (
    id        uuid         NOT NULL,
    parent_id uuid,
    name      varchar(255) NOT NULL,
    slug      varchar(255) NOT NULL,
    version   integer      NOT NULL,
    CONSTRAINT categories_pkey PRIMARY KEY (id)
);
CREATE INDEX categories_parent_id_index ON categories (parent_id);

-- COPY of admin_db.products
CREATE TABLE products (
    id            uuid         NOT NULL,
    category_id   uuid         NOT NULL,
    sku           varchar(64)  NOT NULL,
    name          varchar(255) NOT NULL,
    slug          varchar(255) NOT NULL,
    description   text,
    price_cents   integer      NOT NULL,
    image_url     varchar(255),
    thumbnail_url varchar(255),
    version       integer      NOT NULL,
    created_at    timestamptz  NOT NULL,
    deleted_at    timestamptz,
    CONSTRAINT products_pkey PRIMARY KEY (id)
);
CREATE INDEX products_category_id_index ON products (category_id);

CREATE TABLE orders (
    id                uuid         NOT NULL,
    user_id           uuid         NOT NULL,
    status            order_status NOT NULL DEFAULT 'pending',
    total_cents       integer      NOT NULL,
    payment_reference varchar(255),
    version           integer      NOT NULL DEFAULT 1,
    created_at        timestamptz  NOT NULL DEFAULT now(),
    updated_at        timestamptz  NOT NULL DEFAULT now(),
    CONSTRAINT orders_pkey PRIMARY KEY (id),
    CONSTRAINT orders_user_id_foreign FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE RESTRICT,
    CONSTRAINT orders_total_cents_check CHECK (total_cents >= 0)
);
CREATE INDEX orders_user_id_created_at_index ON orders (user_id, created_at);

-- Product name and price are copied at order time, so later changes don't rewrite past orders
CREATE TABLE order_items (
    id               uuid         NOT NULL,
    order_id         uuid         NOT NULL,
    product_id       uuid         NOT NULL,
    product_name     varchar(255) NOT NULL,
    unit_price_cents integer      NOT NULL,
    quantity         integer      NOT NULL,
    CONSTRAINT order_items_pkey PRIMARY KEY (id),
    CONSTRAINT order_items_order_id_foreign FOREIGN KEY (order_id) REFERENCES orders (id) ON DELETE CASCADE,
    CONSTRAINT order_items_product_id_foreign FOREIGN KEY (product_id) REFERENCES products (id) ON DELETE RESTRICT,
    CONSTRAINT order_items_order_id_product_id_unique UNIQUE (order_id, product_id),
    CONSTRAINT order_items_unit_price_cents_check CHECK (unit_price_cents >= 0),
    CONSTRAINT order_items_quantity_check CHECK (quantity > 0)
);
CREATE INDEX order_items_product_id_index ON order_items (product_id);

-- Current stock per product. The CHECK makes overselling impossible, even if the code had a bug.
CREATE TABLE stock_levels (
    product_id uuid        NOT NULL,
    quantity   integer     NOT NULL DEFAULT 0,
    version    integer     NOT NULL DEFAULT 1,
    updated_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT stock_levels_pkey PRIMARY KEY (product_id),
    CONSTRAINT stock_levels_product_id_foreign FOREIGN KEY (product_id) REFERENCES products (id) ON DELETE RESTRICT,
    CONSTRAINT stock_levels_quantity_check CHECK (quantity >= 0)
);

-- History of every stock change: why it changed and by how much
CREATE TABLE stock_movements (
    id              uuid                  NOT NULL,
    product_id      uuid                  NOT NULL,
    order_id        uuid,
    quantity_change integer               NOT NULL,
    reason          stock_movement_reason NOT NULL,
    created_at      timestamptz           NOT NULL DEFAULT now(),
    CONSTRAINT stock_movements_pkey PRIMARY KEY (id),
    CONSTRAINT stock_movements_product_id_foreign FOREIGN KEY (product_id) REFERENCES products (id) ON DELETE RESTRICT,
    CONSTRAINT stock_movements_order_id_foreign FOREIGN KEY (order_id) REFERENCES orders (id) ON DELETE RESTRICT,
    CONSTRAINT stock_movements_quantity_change_check CHECK (quantity_change <> 0),
    -- Order-related movements must point to their order; manual adjustments must not
    CONSTRAINT stock_movements_order_id_check CHECK ((reason = 'adjustment') = (order_id IS NULL))
);
CREATE INDEX stock_movements_product_id_created_at_index ON stock_movements (product_id, created_at);
CREATE INDEX stock_movements_order_id_index ON stock_movements (order_id);


-- =====================================================================================
-- admin_db — admin-service (Laravel)
-- Laravel's timestamps are second-precision: timestamptz(0)
-- =====================================================================================
\connect admin_db

CREATE TYPE order_status AS ENUM ('pending', 'paid', 'shipped', 'delivered', 'cancelled');
CREATE TYPE import_status AS ENUM ('pending', 'processing', 'completed', 'failed');

-- Nested categories: parent_id points to the parent, NULL = top level
CREATE TABLE categories (
    id         uuid           NOT NULL,
    parent_id  uuid,
    name       varchar(255)   NOT NULL,
    slug       varchar(255)   NOT NULL,
    version    integer        NOT NULL DEFAULT 1,
    created_at timestamptz(0),
    updated_at timestamptz(0),
    CONSTRAINT categories_pkey PRIMARY KEY (id),
    CONSTRAINT categories_parent_id_foreign FOREIGN KEY (parent_id) REFERENCES categories (id) ON DELETE RESTRICT,
    CONSTRAINT categories_slug_unique UNIQUE (slug)
);
CREATE INDEX categories_parent_id_index ON categories (parent_id);

-- Soft-deleted only (never permanently), so ordered products never disappear
CREATE TABLE products (
    id             uuid           NOT NULL,
    category_id    uuid           NOT NULL,
    sku            varchar(64)    NOT NULL,
    name           varchar(255)   NOT NULL,
    slug           varchar(255)   NOT NULL,
    description    text,
    price_cents    integer        NOT NULL,
    image_path     varchar(255),
    thumbnail_path varchar(255),
    version        integer        NOT NULL DEFAULT 1,
    created_at     timestamptz(0),
    updated_at     timestamptz(0),
    deleted_at     timestamptz(0),
    CONSTRAINT products_pkey PRIMARY KEY (id),
    CONSTRAINT products_category_id_foreign FOREIGN KEY (category_id) REFERENCES categories (id) ON DELETE RESTRICT,
    CONSTRAINT products_sku_unique UNIQUE (sku),
    CONSTRAINT products_slug_unique UNIQUE (slug),
    CONSTRAINT products_price_cents_check CHECK (price_cents >= 0)
);
CREATE INDEX products_category_id_index ON products (category_id);

-- COPY of gateway_db.orders. The customer's name and email are copied at order time.
CREATE TABLE orders (
    id             uuid           NOT NULL,
    customer_id    uuid           NOT NULL,
    customer_name  varchar(255)   NOT NULL,
    customer_email varchar(255)   NOT NULL,
    status         order_status   NOT NULL,
    total_cents    integer        NOT NULL,
    version        integer        NOT NULL,
    created_at     timestamptz(0),
    updated_at     timestamptz(0),
    CONSTRAINT orders_pkey PRIMARY KEY (id)
);
CREATE INDEX orders_status_created_at_index ON orders (status, created_at);

-- COPY of gateway_db.order_items. Arrives in the same message as its order, so this foreign key is safe.
CREATE TABLE order_items (
    id               uuid         NOT NULL,
    order_id         uuid         NOT NULL,
    product_id       uuid         NOT NULL,
    product_name     varchar(255) NOT NULL,
    unit_price_cents integer      NOT NULL,
    quantity         integer      NOT NULL,
    CONSTRAINT order_items_pkey PRIMARY KEY (id),
    CONSTRAINT order_items_order_id_foreign FOREIGN KEY (order_id) REFERENCES orders (id) ON DELETE CASCADE
);
CREATE INDEX order_items_order_id_index ON order_items (order_id);
CREATE INDEX order_items_product_id_index ON order_items (product_id);

-- COPY of gateway_db.stock_levels
CREATE TABLE stock_levels (
    product_id uuid    NOT NULL,
    quantity   integer NOT NULL,
    version    integer NOT NULL,
    CONSTRAINT stock_levels_pkey PRIMARY KEY (product_id)
);

-- CSV product imports: progress and the rows that couldn't be imported. Admin panel only — not synced.
CREATE TABLE product_imports (
    id            uuid           NOT NULL,
    file_name     varchar(255)   NOT NULL,
    file_path     varchar(255)   NOT NULL,
    status        import_status  NOT NULL DEFAULT 'pending',
    total_rows    integer        NOT NULL DEFAULT 0,
    imported_rows integer        NOT NULL DEFAULT 0,
    failed_rows   integer        NOT NULL DEFAULT 0,
    errors        jsonb,
    created_at    timestamptz(0),
    updated_at    timestamptz(0),
    CONSTRAINT product_imports_pkey PRIMARY KEY (id)
);
CREATE INDEX product_imports_created_at_index ON product_imports (created_at);
